// Generated by OrchestKit Claude Plugin
// Created: 2026-10-14
//
// Every production build failed from about 2026-10-11: the Vercel NPM_TOKEN
// got 401 on @yonatan-hq/analytics, the stub fallback deleted
// package-lock.json and resolved again, and fumadocs-ui floated from the
// locked 16.15.17 to 16.17.x (TS2724, no useSearchList). The fallback must
// keep every other locked version.
import { execFileSync, spawnSync } from "node:child_process";
import {
	chmodSync,
	cpSync,
	existsSync,
	mkdtempSync,
	readFileSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

const SITE = join(__dirname, "..");
const SCRIPT = join(SITE, "scripts", "vercel-install.sh");

// A fake npm: `ci` fails with a 401 the first time and passes after; every
// call is logged one per line so the test can read the sequence.
const FAKE_NPM = `#!/usr/bin/env bash
echo "$*" >> "$NPM_LOG"
if [[ "$1" == "ci" && ! -f "$NPM_STATE" ]]; then
  touch "$NPM_STATE"
  echo "npm error code E401" >&2
  echo "npm error 401 Unauthorized - GET https://npm.pkg.github.com/x" >&2
  exit 1
fi
exit 0
`;

function runOn401(vercelEnv = "preview"): {
	calls: string[];
	dir: string;
	status: number;
} {
	const dir = mkdtempSync(join(tmpdir(), "vercel-install-"));
	const bin = join(dir, "bin");
	cpSync(join(SITE, "package.json"), join(dir, "package.json"));
	writeFileSync(join(dir, "package-lock.json"), '{"lockfileVersion":3}\n');
	execFileSync("mkdir", ["-p", bin]);
	writeFileSync(join(bin, "npm"), FAKE_NPM);
	chmodSync(join(bin, "npm"), 0o755);
	const log = join(dir, "npm.log");
	const run = spawnSync("bash", [SCRIPT], {
		cwd: dir,
		env: {
			...process.env,
			PATH: `${bin}:${process.env.PATH}`,
			NPM_LOG: log,
			NPM_STATE: join(dir, "state"),
			VERCEL_ENV: vercelEnv,
		},
		stdio: "pipe",
	});
	return {
		calls: readFileSync(log, "utf8").trim().split("\n"),
		dir,
		status: run.status ?? -1,
	};
}

describe("vercel-install.sh on a 401 in production", () => {
	// A prod build must never ship the no-op analytics stub: a dead token
	// fails the build loudly instead (#4737 review).
	it("fails the install and never swaps in the stub", () => {
		const { calls, status } = runOn401("production");
		expect(status).not.toBe(0);
		expect(calls).toEqual([expect.stringMatching(/^ci /)]);
	});
});

describe("vercel-install.sh on a 401 outside production", () => {
	it("keeps package-lock.json, so locked versions do not float", () => {
		const { dir } = runOn401();
		expect(existsSync(join(dir, "package-lock.json"))).toBe(true);
	});

	it("swaps the stub, updates the lock in place, then runs npm ci", () => {
		const { calls } = runOn401();
		expect(calls[0]).toMatch(/^ci /);
		expect(calls).toContainEqual(
			expect.stringMatching(/^pkg set dependencies\.@yonatan-hq\/analytics=file:/),
		);
		expect(calls).toContainEqual(expect.stringMatching(/--package-lock-only/));
		expect(calls[calls.length - 1]).toMatch(/^ci /);
	});
});

describe("fumadocs pins", () => {
	it("pins fumadocs-ui and fumadocs-core to exact versions", () => {
		const pkg = JSON.parse(readFileSync(join(SITE, "package.json"), "utf8"));
		for (const name of ["fumadocs-ui", "fumadocs-core"]) {
			expect(pkg.dependencies[name], name).toMatch(/^\d+\.\d+\.\d+$/);
		}
	});
});
